/* ❓ Tulong / FAQ bot — search-based (walang AI/server): hinahanap ang pinakamalapit na FAQ; kapag wala, puwedeng mag-ticket sa admin.
   Mga FAQ ay may built-in + mga idinagdag ng Admin (help_faq). Ang mga sagot ng admin sa ticket ay puwedeng gawing FAQ. */
(function () {
  const E = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const N = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const SEED = [
    ['POS', 'Paano magbukas ng araw (opening) at mag-Z-read?', 'Sa POS → Shift: ilagay ang opening cash at i-confirm para magbukas. Sa pagsasara, i-click ang Z-read. Hindi makakapag-Z-read kapag may bukas pang table; kailangan munang i-settle o i-cancel. Ang araw ay pinuputol ng 5 AM.', 'opening shift z-read zread isara bukas cash'],
    ['POS', 'Paano kumuha ng order sa table?', 'Tables tab → pindutin ang table → ilagay ang pax → Order. Piliin ang Dine-in o Take-out sa bawat order. Para magdagdag, pindutin ulit ang table at piliin ang "Bagong order"; iisang resibo pa rin ito.', 'table order dine-in takeout magdagdag add order'],
    ['POS', 'Paano mag-split ng bill?', 'Sa order, piliin kung para kanino ang bawat order (customer/member). Sa pagbabayad, awtomatikong hahatiin ang bill ayon sa may-ari ng order.', 'split bill hati hatiin'],
    ['POS', 'Paano mag-discount (Senior/PWD/Comp/manual)?', 'Sa bayad screen, pindutin ang Discount. Kailangan ng manager code (exempt ang admin). Puwede ring per-item (🏷️) o sa buong total, ₱ o %.', 'discount senior pwd comp complimentary manager code'],
    ['POS', 'Paano mag-void ng order o sale?', 'Kailangan ng manager code. Pumunta sa Sales/History, piliin ang sale, i-void at ilagay ang dahilan. Naibabalik ang voucher, gift card at points.', 'void cancel kanselahin'],
    ['POS', 'Hindi ko mabuksan ang table, sinasabing ginagamit ng iba.', 'Isang user lang ang puwedeng gumamit ng table. Kung kailangan mong kunin, humingi ng manager PIN para sa takeover. Purple = gamit ng iba, blue = akin.', 'takeover table lock ginagamit iba'],
    ['POS', 'Paano magbayad gamit ang voucher?', 'Bayad → Voucher → i-type ang series number (hal. KV-000123 o 123). Isang beses lang magagamit, walang sukli, at bawal sa order na may discount. Kung kulang, dagdagan ng cash/card. Kailangang approved at may naka-assign na may-ari ang voucher (Admin → Vouchers).', 'voucher series bayad sukli'],
    ['POS', 'Paano gamitin ang gift card o points?', 'Bayad → Gift Card (i-type ang series) o Points (piliin muna ang member). Nababawasan ang balanse; walang sukli. Ang points ay kinikita sa bawat bayad ng member kapag naka-on sa 🎁 Gift Card / Points → Loyalty settings.', 'gift card points loyalty'],
    ['POS', 'Paano mag-reserve ng table o meeting room?', 'Reservations tab → Bago. Piliin ang petsa/oras, table sa layout map (o buong layout), at guest. May advance order (searchable); kung required ang membership sa table, pumili muna ng member. May alarm 30 minuto bago ang oras para tawagan ang guest.', 'reservation reserve meeting room advance order'],
    ['POS', 'Bakit hindi ako makapag-order pagkatapos ng 9PM?', 'May kitchen cut-off. Admin o manager code lang ang puwedeng mag-override.', 'cutoff cut-off 9pm kitchen'],
    ['POS', 'Paano mag-reprint ng kitchen ticket?', 'Sa table, sa order row, pindutin ang 🔁 Kusina. Para sa hindi pa lumalabas na items.', 'reprint kitchen ticket print'],
    ['POS', 'Ano ang 🔥 Fire / Course 2 at 3?', 'Ang item na Course 2 o 3 ay naka-hold at hindi pa napi-print sa kusina. Pindutin ang 🔥 Fire sa table kapag handa na para sa susunod na course.', 'course fire hold appetizer dessert'],
    ['POS', 'Paano gamitin ang 📱 Waiter at QR orders?', 'Waiter tab: ➕ Order para kumuha ng order, 🔔 Bill para ipaalam sa cashier. May 📥 QR inbox kapag nag-order ang customer sa QR; tanggapin ito para mapunta sa kusina.', 'waiter qr order inbox handheld'],
    ['POS', 'Paano mag-print ulit ng resibo?', 'Sales/History → piliin ang sale → Print. Naka-set sa Setup kung itatago ang membership info (asterisk).', 'resibo receipt reprint'],
    ['POS', 'Paano i-search ang member?', 'I-type ang ID o pangalan (kahit gitna ng salita) at pindutin ang Hanapin o Enter. Sa Members, i-check ang mga resulta para sa bulk na pag-assign ng club.', 'member search hanapin club'],
    ['POS', 'Paano mag-upload ng menu nang sabay-sabay?', 'Menu → ⬆️ Bulk upload (CSV). I-download muna ang template. Updated ang item na kapangalan; bago ang wala pa.', 'menu upload csv bulk'],
    ['POS', 'Paano gumawa ng event menu?', 'Events → piliin ang event → 📋 Kopyahin mula sa Main Menu. Palitan ang presyo, at ✏️ i-edit ang kopya para sa grammage ng sangkap.', 'event menu kopya presyo grammage'],
    ['ERP', 'Nakalimutan ko ang password.', 'Sa login, gamitin ang reset. Kung hindi gumana, hilingin sa Admin na i-reset o i-force ang bagong password sa susunod na login (Admin → Account Access).', 'password nakalimutan reset login'],
    ['ERP', 'Saan ko makikita ang isang user o ang access niya?', 'Admin → Account Access; i-click ang user para i-edit, i-reset ang password, o i-delete.', 'user access account saan hanapin'],
    ['ERP', 'Saan ang backup at restore?', 'Admin → Backup. May manual backup, restore point, import at export. Makikita ang progreso sa status label (task tray) kahit isara ang modal.', 'backup restore import export'],
    ['ERP', 'Paano gumawa ng vouchers?', 'Admin → Vouchers → Gumawa ng series. Ipa-sign sa COO/President, i-approve ng Super Admin, tapos i-assign ang may-ari.', 'voucher series approve assign'],
    ['ERP', 'Saan makikita ang benta ng lahat ng branch?', 'Admin → 📊 POS Dashboard (Admin lang).', 'dashboard benta sales branch'],
    ['ERP', 'Paano mag-secret recipe?', 'Sa BOM, i-set ang password sa recipe. Nakatago ang sangkap at gramo pero buo ang costing at inventory. Ang gumawa lang ang puwedeng mag-reset ng password.', 'secret recipe bom password']
  ];
  const BOOK = [["ERP", "Ano ang KusinaERP?", "Ang KusinaERP ay sistemang pang-negosyo para sa kumpanyang may commissary (planta) at maraming branch. Nasa isang lugar ang lahat: pag-order ng branch, produksyon, inventory, pagbili sa supplier, singilan, HR, payroll, at accounting books. Dahil nasa browser lang ito, gumagana ito sa computer, tablet, o cellphone.\nMETA: Para kanino: Admin, Accounting, HR, Branch, Commissary | Ginagamit sa: Browser (Chrome ang inirerekomenda)\n- Isang login, iisang data. Ang order ng branch ay kusang lumalabas sa commissary, at ang resibo nito ay kusang pumapasok sa AR at sa books.\n- May access control. Bawat tao ay may role at makikita lang ang mga menu na para sa kanya.\n- May talaan ng lahat ng ginawa. Ang bawat mahalagang aksyon ay nakatala sa Audit Logs.\n- Mas mura. Walang buwanang bayad sa ibang software; ang tanging gastos ay ang Firebase at hosting.", "Ano ang KusinaERP? Bahagi 1 — Pagkilala sa KusinaERP"], ["ERP", "Mga role at kung ano ang nakikita nila", "| Role | Pangunahing gamit | Screen |\n| Admin / Super Admin | Lahat ng module, user access, menu visibility, backups | Admin |\n| Accounting | Accounting (Books), AR, AP, Payroll, Finance | Admin (ayon sa access) |\n| HR | Employee DB, Attendance, Leave, Loan, Memo, HR Documents | Admin (ayon sa access) |\n| Branch (Manager / Staff) | Place Order, Deliveries, Inventory Count, Prime Cost, Attendance, Loan Ko | Branch |\n| Commissary | Order Fulfillment, Plant Inventory, Direct Receiving, Spoilage, Price Sheet, AR | Commissary |\n> TIP: Ang Super Admin lang ang puwedeng magbago ng Menu Visibility at ng access ng ibang tao. Isa lang ang Super Admin.", "Mga role at kung ano ang nakikita nila Bahagi 1 — Pagkilala sa KusinaERP"], ["ERP", "Unang beses mag-login", "1. Buksan ang website ng KusinaERP sa Chrome.\n2. I-type ang email at password na ibinigay ng Admin, at pindutin ang Login.\n3. Awtomatiko kang dadalhin sa tamang screen (Admin, Branch, o Commissary) ayon sa role mo.\n4. Sa kaliwa ay ang menu. I-click ang gusto mong gamitin.\n5. Sa katapusan ng trabaho, pindutin ang Logout.\n> WARN: Huwag ibigay ang password sa iba. Kung may pagbabago sa tao (resign, lipat), sabihan agad ang Admin para ma-disable ang account.", "Unang beses mag-login Bahagi 1 — Pagkilala sa KusinaERP"], ["ERP", "Mga karaniwang bagay sa lahat ng screen", "- 🔄 Refresh — i-reload ang listahan para makita ang pinakabagong data.\n- 🔎 Search box — mag-type ng bahagi ng pangalan o code; ang ibang dropdown ay puwedeng hanapin sa pamamagitan ng pag-type.\n- 📥 Export CSV / 📤 Import CSV / 📄 Template — para sa maramihang paglagay ng data sa Excel. Laging i-download muna ang Template.\n- 🖨️ Print — nagbubukas ng printable na bersyon na may header ng kumpanya.\n- ❓ Gabay — may maikling paliwanag sa ilang screen (hal. AR Ledger at Accounting).\n- Kulay ng status — berde = ayos, dilaw = babala, pula = may problema.", "Mga karaniwang bagay sa lahat ng screen Bahagi 1 — Pagkilala sa KusinaERP"], ["ERP", "Lahat ng module sa isang tingin", "| Grupo | Mga module |\n| Overview | 📊 Dashboard |\n| Operations | Products Master · Manufacturing · Recipe Costing · Lot & Expiry · Spoilage · Auto-PR (Low Stock) |\n| Procurement at AP | Purchase Orders · A/P Invoices · Vendors |\n| Sales at Customers | Customers · Branch Disputes · AR Ledger · Price Lists · Daily Price Sheet |\n| Inventory | Branch Inventory · Inventory Totals · SAP Item Master · Storage Stations · BOM Management |\n| Finance | General Ledger · Prime Cost Management · Accounting (Books) · Assets |\n| HR | Employee DB · Position Management · Attendance · Payroll / Payslip · Loan Management · LST · HR Documents · Memo / Announcement |\n| System | Menu Visibility · Online / Logout Users · System Health · Audit Logs · Backups · Branding · Company Management · Mga Request |\n| Branch screen | Place Order · My Deliveries · Prime Cost · Loan Ko · Attendance · Order Board · HR Documents · Mga Request · Inventory Count |\n| Commissary screen | Order Fulfillment Queue · Plant Inventory · Direct Receiving · Report Spoilage · Attendance · Order Board · HR Documents · Mga Request · Daily Price Sheet · AR Ledger |", "Lahat ng module sa isang tingin Bahagi 2 — Mapa ng mga Menu at Paghahambing"], ["Admin", "Unang setup na dapat gawin", "1. Mag-login bilang Admin at buksan ang Company Management: ilagay ang bawat company.\n2. Sa System Branding, ilagay ang pangalan, address, TIN, at logo para sa header ng mga resibo at report.\n3. Sa Users, gumawa ng account ng bawat tao at piliin ang role.\n4. Sa Menu Visibility (Super Admin), itago ang mga menu na hindi pa gagamitin.\n5. Sa Employee DB, ilagay ang mga empleyado (gamitin ang Import CSV kung marami).\n6. Sa Products Master, ilagay ang mga produkto, presyo at conversion.\n7. Sa Vendors at Customers, ilagay ang mga supplier at customer.\n8. Sa Accounting (Books) → Setup, gumawa ng Default COA.\n> TIP: Gawin ang setup nang paisa-isang company para hindi magkahalo ang data.", "Unang setup na dapat gawin Bahagi 3 — Pag-setup (para sa Admin)"], ["Admin", "Users, role at access", "- Ang bawat module ay may antas ng access: Walang access, View, o Edit.\n- Ang Super Admin ang nagtatakda nito sa User Access.\n- Ang Area Manager ay may mga branch na nakatalaga (sa Position Management).\n> NOTE: Kapag nagbago ang access, hilingin sa user na mag-logout at mag-login ulit.", "Users, role at access Bahagi 3 — Pag-setup (para sa Admin)"], ["Admin", "Menu Visibility (Super Admin lang)", "Itinatago nito ang mga menu para sa lahat ng user nang hindi binubura ang feature. Kapag may bagong module, i-check ito dito para lumabas.\n1. Buksan ang 🙈 Menu Visibility.\n2. I-check o i-uncheck ang mga module.\n3. I-save, at mag-refresh ang mga user.", "Menu Visibility (Super Admin lang) Bahagi 3 — Pag-setup (para sa Admin)"], ["Admin", "Pag-update ng sistema (para sa developer o Admin)", "1. Unahin ang firestore.rules: kopyahin sa Firebase Console → Firestore → Rules → Publish.\n2. I-upload ang mga bagong file (app.js, *.html, *.js) sa GitHub.\n3. Hintayin ang GitHub Pages (karaniwang ilang minuto).\n4. Pindutin ang Ctrl+F5 para ma-clear ang lumang cache.\n> WARN: Kapag nauna ang upload kaysa sa rules, lalabas ang \"Missing or insufficient permissions\" o \"No access\" sa mga bagong feature.", "Pag-update ng sistema (para sa developer o Admin) Bahagi 3 — Pag-setup (para sa Admin)"], ["ERP", "Dashboard", "META: Sino: Admin | Menu: 📊 Dashboard\nIpinapakita ang buod ng benta, demand ng branch, at mga babala. 🔄 Refresh Analytics para sa pinakabagong numero. Ang Commissary ay may sariling dashboard ng mga order at dispatch.", "Dashboard Bahagi 4 — Operations at Inventory"], ["ERP", "Products Master", "META: Sino: Admin | Menu: 📦 Products Master\nPara saan: ang listahan ng lahat ng produktong ino-order ng branch, kasama ang presyo, UOM at conversion.\nMahahalagang field\n| Field | Ibig sabihin |\n| SRP Whole / SRP Loose | Presyo na binabayaran ng branch (paninda). Ito lang ang nakikita ng branch. |\n| Supplier Price | Presyo ng supplier sa atin. Hindi nakikita ng branch. Ang Loose ay kusang hinahati ayon sa Conversion. |\n| Puhunan (Cost) | Gastos ng produkto. Kung 0 pa, ang Supplier Price ang kusang magiging Puhunan. |\n| Conversion | Ilang Loose ang laman ng 1 Whole (buong numero). |\n| Laman ng Whole / Loose | Gramo o ml ng bawat isa. Mula rito lumalabas ang presyo bawat gramo. |\n| Supplier / Company | Para sa filter at pagtatalaga ng produkto sa company. |\nMagdagdag ng produkto\n1. Pindutin ang ➕ Mag-add ng Produkto.\n2. Ilagay ang pangalan, code, UOM ng Whole at Loose, at supplier.\n3. Ilagay ang Supplier Price at SRP; tingnan ang margin box.\n4. Ilagay ang laman sa gramo/ml at pindutin ang ↔️ Gamitin bilang Conversion kung gusto.\n5. I-save.\nMaramihang upload\nGamitin ang 📄 Blank Template at Upload & Sync. Mga column para sa presyo: cost_whole, cost_loose, supplier_price, supplier_price_loose, content_whole, content_loose, content_unit (g o ml).\n> TIP: Gamitin ang supplier filter sa itaas ng listahan para makita ang mga produkto ng isang supplier lang.\n> WARN: Ang Puhunan at Supplier Price ay nakatago sa branch at naka-save sa hiwalay na secure na talaan. Huwag ibahagi ang CSV na may cost.", "Products Master Bahagi 4 — Operations at Inventory"], ["ERP", "Manufacturing at BOM", "META: Sino: Admin, Commissary | Menu: 🏭 Manufacturing, 🧪 BOM Management\nPara saan: ang recipe (BOM) at ang pagtatala ng produksyon.\n1. Buksan ang BOM Management at piliin ang company.\n2. Pindutin ang ➕ Add Recipe (BOM) at ilagay ang pangalan, code at UOM ng nagagawa.\n3. Magdagdag ng sangkap: hanapin sa listahan. May tatlong pinagmumulan: Product Master, SAP Items, at R&D ingredient (hindi pa sa SAP; ilagay ang presyo bawat gramo o piraso).\n4. Ilagay ang dami at yield ng bawat sangkap; kusang kinukuwenta ang gastos.\n5. Ilagay ang nagagawang dami para makuha ang gastos kada gramo.\n6. I-check ang 🛒 Gawing Product din kung ibebenta ito sa branch o customer.\n7. I-save.\nAng BOM ay sangkap na rin\nAng bawat naka-save na BOM ay lumalabas na rin sa listahan ng sangkap ng ibang BOM (may \"(BOM)\" sa pangalan), kaya puwedeng gumawa ng recipe na gumagamit ng nauna nang prep (hal. sauce → ulam).\n> NOTE: Ang BOM ay hindi puwedeng maging sangkap ng sarili niya o ng BOM na gumagamit na sa kanya.\nGawing Product\nGagawa ang sistema ng item sa Product Master na nakatago (inactive) sa branch. Ilagay ang SRP sa Product Master at i-activate para makita at ma-order ng branch o customer.\nStart Production\nPindutin ang ➕ Start Production para itala ang batch: hinahango ang sangkap sa stock at nadaragdag ang tapos na produkto.", "Manufacturing at BOM Bahagi 4 — Operations at Inventory"], ["ERP", "Recipe Costing", "META: Sino: Admin | Menu: 📈 Recipe Costing\nIpinapakita ang gastos ng bawat recipe batay sa kasalukuyang presyo ng sangkap. Pindutin ang 🔄 Recalculate Costs pagkatapos magbago ang presyo.", "Recipe Costing Bahagi 4 — Operations at Inventory"], ["ERP", "Lot at Expiry", "META: Sino: Admin, Commissary | Menu: 🏷️ Lot & Expiry\nNagtatala ng lot number at petsa ng pagkaubos ng bawat batch. Gamitin ito para masundan ang pinagmulan ng produkto (lot tracing) at para mabantayan ang malapit nang mag-expire.", "Lot at Expiry Bahagi 4 — Operations at Inventory"], ["ERP", "Spoilage", "META: Sino: Commissary (nag-uulat), Admin (nag-aapruba) | Menu: 🗑️ Spoilage, 📉 Report Spoilage\n1. Commissary: pindutin ang Report Spoilage, piliin ang produkto, dami at dahilan.\n2. Admin: buksan ang Spoilage at suriin ang mga request.\n3. Aprubahan o tanggihan; kapag inaprubahan, babawasan ang stock.\n> TIP: Maglagay ng malinaw na dahilan para madaling suriin sa Variance Report.", "Spoilage Bahagi 4 — Operations at Inventory"], ["ERP", "Auto-PR (Low Stock)", "META: Sino: Admin | Menu: 🤖 Auto-PR (Low Stock)\nNaglilista ng mga produktong mababa na ang stock ayon sa buffer limit, para madali kang makagawa ng Purchase Request o PO.", "Auto-PR (Low Stock) Bahagi 4 — Operations at Inventory"], ["ERP", "Inventory (Branch, Plant, Totals, SAP)", "| Module | Para saan |\n| 📋 Inventory Count (Branch) | Bilang ng stock ng branch; may 📷 Scan ng barcode |\n| 📋 Plant Inventory (Commissary) | Stock ng planta; ➕ Add / Tag Product, Scan, Save |\n| 📦 Inventory Totals | Kabuuang stock (Beginning/Ending) para sa food cost |\n| 📒 SAP Item Master | Listahan ng items kada company, kasama ang presyo at UOM |\n| 🏷️ Storage Stations | Mga custom na lokasyon ng imbakan at UOM |\nMagbilang ng stock (Branch)\n1. Buksan ang Inventory Count.\n2. Hanapin o i-scan ang item at ilagay ang bilang.\n3. I-save/Submit. Itatala ang bilang at ihahambing sa inaasahan.", "Inventory (Branch, Plant, Totals, SAP) Bahagi 4 — Operations at Inventory"], ["ERP", "Daloy ng order", "FLOW: Branch: Place Order > Commissary: Fulfillment Queue > Delivery > Branch: Tanggap o Dispute > AR Ledger > Accounting", "Daloy ng order Bahagi 5 — Order, Delivery at Singilan"], ["ERP", "Place Order (Branch)", "META: Sino: Branch | Menu: 🛒 Place Order\n1. Pindutin ang ➕ Start Order at piliin ang catalog.\n2. Hanapin o i-scan ang produkto at I-add sa Cart.\n3. Tingnan ang 👁️ Print Preview ng Resibo.\n4. Pindutin ang ✅ SUBMIT ORDER SA COMMISSARY.\n> TIP: Ang presyong nakikita ng branch ay ang SRP. Hindi nito nakikita ang supplier price o puhunan.", "Place Order (Branch) Bahagi 5 — Order, Delivery at Singilan"], ["ERP", "Order Fulfillment (Commissary)", "META: Sino: Commissary | Menu: 📦 Order Fulfillment Queue\n1. Buksan ang queue at piliin ang order.\n2. Ihanda ang mga item at ilagay ang aktuwal na dami.\n3. I-update ang status at ipadala; may print ng SI/resibo.\n4. Itala ang delivery personnel (Logistics Team).", "Order Fulfillment (Commissary) Bahagi 5 — Order, Delivery at Singilan"], ["ERP", "My Deliveries at Dispute", "META: Sino: Branch | Menu: 🚚 My Deliveries, 🚨 Branch Disputes\n1. Pagdating ng delivery, buksan ang My Deliveries at suriin ang dami at kondisyon.\n2. Kung may kulang o sira, mag-file ng dispute na may paliwanag.\n3. Nakikita ng Admin ang mga ito sa Branch Disputes para i-resolba.", "My Deliveries at Dispute Bahagi 5 — Order, Delivery at Singilan"], ["ERP", "Direct Receiving", "META: Sino: Commissary | Menu: 🚚 Direct Receiving\nPara sa mga dumating mula sa supplier nang direkta sa planta. Itala ang dumating at i-update ang inventory.", "Direct Receiving Bahagi 5 — Order, Delivery at Singilan"], ["ERP", "Order Board", "META: Sino: Lahat ng may access | Menu: 📦 Order Board\nPangkalahatang tanaw sa mga order at status nila para madaling masundan.", "Order Board Bahagi 5 — Order, Delivery at Singilan"], ["ERP", "Daily Price Sheet at Price Lists", "META: Sino: Commissary, Admin | Menu: 💱 Daily Price Sheet, 💲 Price Lists\n- Price Lists — ang mga presyo ng bawat company/customer.\n- Daily Price Sheet — arawang presyo na ginagamit sa pagsingil.", "Daily Price Sheet at Price Lists Bahagi 5 — Order, Delivery at Singilan"], ["ERP", "AR Ledger (Singilan)", "META: Sino: Accounting, Commissary | Menu: 📒 AR Ledger\nPara saan: ang listahan ng mga dapat bayaran ng customer o branch at ang mga bayad nila.\n1. Piliin ang company (filter sa itaas) at ang tab na kailangan.\n2. Hanapin ang customer o SI number.\n3. Pindutin ang bayad, ilagay ang halaga, petsa at paraan ng bayad.\n4. May ❓ Gabay sa bawat dropdown at button.\n> NOTE: Awtomatikong binabasa ng Accounting (Books) ang mga order at bayad dito bilang benta at collection, kaya hindi na kailangang i-encode ulit.", "AR Ledger (Singilan) Bahagi 5 — Order, Delivery at Singilan"], ["ERP", "Vendors", "META: Sino: Admin | Menu: 🏢 Vendors\nIlagay ang pangalan, TIN, contact at terms. Gamitin ang ⬆️ Import CSV para sa marami; ang 📄 Template ang gabay sa columns.", "Vendors Bahagi 6 — Purchasing at A/P"], ["ERP", "Purchase Orders", "META: Sino: Admin | Menu: 📝 Purchase Orders\n1. ➕ Create New PO, piliin ang vendor at company.\n2. Idagdag ang mga item, dami at presyo.\n3. I-print o i-send; may ⚙️ Signatories para sa pirma.\n4. Kapag dumating ang item, i-receive ito (puwedeng i-scan ang PO barcode).\n5. Ang mga natanggap pero hindi pa na-invoice ay nasa 📑 GRPO.", "Purchase Orders Bahagi 6 — Purchasing at A/P"], ["ERP", "A/P Invoices", "META: Sino: Accounting | Menu: 🧾 A/P Invoices\nListahan ng mga utang sa supplier mula sa mga natanggap na PO. Itala ang bayad (kasama ang down payment). Ang mga bayad ay napupunta sa General Ledger at, sa pamamagitan ng sync, sa Accounting (Books).", "A/P Invoices Bahagi 6 — Purchasing at A/P"], ["ERP", "Customers", "META: Sino: Admin | Menu: 👥 Customers\nListahan ng mga customer at branch na sinisingil. May Export/Import CSV at Print.", "Customers Bahagi 6 — Purchasing at A/P"], ["ERP", "Simulan: Setup", "1. Buksan ang ⚙️ Setup at pindutin ang ✨ Gumawa ng Default COA (Philippine). Maaari ding mag-import ng sariling COA gamit ang CSV.\n2. I-edit ang mga bank account at i-check ang Bank/Cash para lumabas sa Bank Rec.\n3. Piliin ang company sa itaas, at i-check ang VAT-registered kung saklaw ng VAT.\n4. Piliin ang Default cash/bank account at ang company ng lumang General Ledger.\n5. Ilagay ang opening balances gamit ang Journal o ang Import Journal CSV mula sa QuickBooks.\n> TIP: Ang bawat company ay may sariling books, pero iisa ang Chart of Accounts.", "Simulan: Setup Bahagi 7 — Accounting (Books)"], ["ERP", "Journal", "1. ➕ Bagong Journal, piliin ang petsa at memo.\n2. Sa bawat linya: account, at debit o credit, hindi pareho.\n3. Hintayin ang berdeng \"✔ Balanse\" bago I-post.\n4. Kung may mali, huwag burahin: pindutin ang ↩️ Reverse, saka gumawa ng tamang entry.\n> NOTE: Hindi nababago ang naka-post na entry. Ito ay para sa audit at para tugma ang books.", "Journal Bahagi 7 — Accounting (Books)"], ["ERP", "Gastos / Bill", "Mabilis na paglagay ng gastos.\n1. Piliin ang petsa, payee, at account ng gastos.\n2. Ilagay ang halaga at piliin ang VAT (kasama, dagdag, o wala).\n3. Piliin ang EWT (1%, 2%, 5%, 10%, 15%) kung may withholding.\n4. Piliin ang pinagbayaran (bank/cash) o 2000 Accounts Payable kung utang pa.\n5. I-post. Kusang kinukuwenta ang Input VAT at EWT payable.", "Gastos / Bill Bahagi 7 — Accounting (Books)"], ["ERP", "Bank Reconciliation", "1. Piliin ang bank at ang statement date, at ilagay ang ending balance sa statement.\n2. Opsyonal: 📤 Statement CSV (may columns na Date at Amount, o Deposit at Withdrawal) para awtomatikong mag-match.\n3. I-tick ang mga linyang nasa statement.\n4. Dapat 0.00 ang Difference; saka I-save.\n> TIP: Ang mga hindi na-tick ay mga \"outstanding\" (hal. tseke na hindi pa na-encash).", "Bank Reconciliation Bahagi 7 — Accounting (Books)"], ["ERP", "Mga ulat", "| Ulat | Gamit |\n| Trial Balance | Tingnan kung balanse ang books sa isang petsa |\n| Income Statement | Kita, gastos at net income sa isang panahon |\n| Balance Sheet | Assets, Liabilities at Equity |\n| General Ledger | Lahat ng galaw ng isang account na may running balance |\n| Cash Movement | Pasok at labas ng cash/bank |\nLahat ay may 🖨️ Print at 📥 CSV.", "Mga ulat Bahagi 7 — Accounting (Books)"], ["ERP", "Invoice, Credit Memo at Statement of Account", "1. ➕ Invoice: ilagay ang customer, VAT type at mga item. Magpo-post ng Dr AR / Cr Sales / Cr Output VAT.\n2. 💵 Bayad: ilagay ang natanggap; ilagay din ang na-withhold ng customer (2307) kung meron.\n3. Void ay gumagawa ng reversal; magagawa lang kung wala pang bayad.\n4. Credit Memo (customer) at Vendor Credit ay para sa return at adjustment.\n5. 📄 Statement of Account ay may aging (Current, 1-30, 31-60, 61-90, 90+).", "Invoice, Credit Memo at Statement of Account Bahagi 7 — Accounting (Books)"], ["ERP", "VAT at EWT", "- Ipinapakita ang Output VAT, Input VAT at VAT payable sa napiling panahon.\n- Nakalista ang EWT bawat payee; 🖨️ 2307 ay draft na gabay sa pag-encode sa opisyal na form.\n> WARN: Gabay lang ang mga ulat na ito sa paghahanda ng BIR returns. Ipa-review sa accountant bago mag-file.", "VAT at EWT Bahagi 7 — Accounting (Books)"], ["ERP", "Budget at Recurring", "- Budget: maglagay ng budget kada account kada buwan; makikita ang variance at YTD.\n- Recurring: gumawa ng buwanang entry (renta, depreciation). Pindutin ang ▶️ Patakbuhin ang due para magawa ang mga hindi pa nagagawa; hindi ito nagdodoble.", "Budget at Recurring Bahagi 7 — Accounting (Books)"], ["ERP", "Month-end lock", "Sa Setup, ilagay ang petsa sa 🔒 I-lock ang books hanggang. Walang ma-pa-post na entry sa o bago ng petsang iyon. Admin lang ang puwedeng mag-lock o mag-unlock.", "Month-end lock Bahagi 7 — Accounting (Books)"], ["ERP", "Awtomatikong galing sa ERP", "Kapag binuksan ang tab, kusang napo-post ang:\n- AR orders bilang benta at ang bayad ng customer (Dr Cash / Cr AR).\n- Lumang General Ledger: payroll at bayad sa PO. Ang hindi tukoy ay napupunta sa 9999 Suspense para i-reclassify mo.\n> NOTE: Hindi pa awtomatiko ang depreciation ng Assets at ang inventory/COGS. Gamitin muna ang Recurring o manual na Journal.", "Awtomatikong galing sa ERP Bahagi 7 — Accounting (Books)"], ["ERP", "Paglipat mula sa QuickBooks", "1. I-export ang Chart of Accounts at Import COA CSV (Code, Name, Type, Bank).\n2. Maglagay ng opening balances (Trial Balance ng QuickBooks sa petsa ng paglipat).\n3. Patakbuhin ang dalawa nang 1 hanggang 2 buwan at ihambing ang Trial Balance.\n4. Kapag tugma, saka lang ihinto ang QuickBooks.", "Paglipat mula sa QuickBooks Bahagi 7 — Accounting (Books)"], ["ERP", "General Ledger (Finance Dashboard)", "META: Sino: Accounting | Menu: 🏦 General Ledger\nAng cash ledger ng ERP: Set Balance, Z-Reading, at Sync. Ang mga galaw dito (payroll, bayad sa PO) ang binabasa ng Accounting (Books).", "General Ledger (Finance Dashboard) Bahagi 7 — Accounting (Books)"], ["ERP", "Prime Cost Management", "META: Sino: Branch Manager, Admin | Menu: 💰 Prime Cost\nPara saan: weekly na prime cost (food cost + labor) ng bawat branch.\n1. Piliin ang branch at ang linggo (Lunes).\n2. Ilagay ang benta, covers, channels, petty cash, purchases at inventory.\n3. Ilagay ang oras ng mga empleyado sa Labor.\n4. Tingnan ang resulta: Food cost %, Labor %, Prime cost %, Gross margin.\n> NOTE: Ang manager ng branch at ang Admin lang ang nag-eedit; ang Setup, rates at P&L ay Admin. Kapag locked ang linggo, read-only na ito.", "Prime Cost Management Bahagi 7 — Accounting (Books)"], ["ERP", "Assets", "META: Sino: Admin | Menu: 🏗️ Assets\nListahan ng kagamitan at maintenance. ➕ Add Asset para magdagdag.", "Assets Bahagi 7 — Accounting (Books)"], ["ERP", "Employee DB (Masterlist)", "META: Sino: HR, Admin | Menu: 🧑‍💼 Employee DB\nFilter, search at export\n- Status filter: Lahat, Active, Inactive (Resigned/Terminated), On-Leave. Ipinapakita sa ilalim ang bilang.\n- Search: pangalan, position, company, o Employee ID.\n- 📥 Export CSV ay sumusunod sa filter.\nMagdagdag o mag-update\n1. ➕ Add Employee at kumpletuhin ang Personal, Employment, Government, Payroll at Documents.\n2. I-save.\nBulk update gamit ang CSV\n1. Pindutin ang 📄 Template o 📥 Export CSV (para sa kasalukuyang data).\n2. Ayusin sa Excel. Huwag baguhin ang Employee_ID.\n3. 📤 Import CSV, tingnan ang preview, at kumpirmahin.\n> NOTE: Naka-link ang litrato at dokumento sa Employee ID kaya hindi ito apektado ng import. Ang blangkong cell ay hindi ginagalaw, kaya walang nabubura. Ang bagong empleyado (walang ID) ay awtomatikong bibigyan ng ID.\n> WARN: Siguraduhing YYYY-MM-DD ang petsa, at Active / On-Leave / Resigned / Terminated lang ang Status.", "Employee DB (Masterlist) Bahagi 8 — HR at Payroll"], ["ERP", "Position Management", "META: Sino: HR, Admin | Menu: 👔 (sa Employee DB)\n- Listahan ng mga position na may uri: general, unique (isa lang ang may hawak, hal. President, COO), o branches.\n- May approver ang ilang position na nakaugnay sa email setting ng mga request.\n- Employee History: itala ang promosyon, pagbabago ng sahod at kalakip na file.\n- Ang Job Title at Reporting Officer ay pinipili mula sa listahan (searchable), hindi tina-type.\n- Ang Area Manager ay may nakatalagang mga branch.", "Position Management Bahagi 8 — HR at Payroll"], ["ERP", "Attendance, Leave at Schedule", "META: Sino: Lahat | Menu: 🕒 Attendance\n- Itala ang oras at i-file ang request (OB, OT, Leave) mula sa Attendance.\n- Leave: SIL at Vacation Leave; piliin kada araw kung with pay o without pay. Ang with pay ang bumabawas sa credit.\n- Ang credit ay awtomatikong bumabalik sa simula ng taon (Enero 1). Ang HR ang nagtatakda ng default sa 🏖️ Default Leave at puwedeng baguhin kada empleyado.\n- Ang aprubadong Leave ay kusang kasama sa payroll computation bilang paid o unpaid day.", "Attendance, Leave at Schedule Bahagi 8 — HR at Payroll"], ["ERP", "LST (Schedule at Manning)", "META: Sino: HR, Area Manager | Menu: 🗓️ LST Management\nPagbuo ng schedule ng mga tauhan kada site. Ang Area Manager ay nakakakita lang ng mga branch na nakatalaga sa kanya.", "LST (Schedule at Manning) Bahagi 8 — HR at Payroll"], ["ERP", "Payroll / Payslip", "META: Sino: HR, Accounting | Menu: 💸 Payroll\n1. ➕ Generate Payslip at piliin ang empleyado at panahon.\n2. Suriin ang oras, leave, allowance at kaltas.\n3. I-save at i-print ang payslip.\n> NOTE: Ang pag-release ng payroll ay naitatala sa General Ledger at nasasama sa Accounting (Books) bilang gastos sa sahod.", "Payroll / Payslip Bahagi 8 — HR at Payroll"], ["ERP", "Loan Management", "META: Sino: HR, President/Approver | Menu: 🏦 Loan Management, 🏦 Loan Ko\nFLOW: Aplikasyon > Aprubal ng President > Kontrata (i-print at pirmahan) > I-upload ang pirmadong kopya > Active > Pagbabayad hanggang Paid\n1. Setup (Super Admin): tukuyin ang President ng bawat company, mga patakaran (haba ng serbisyo, bilang ng aktibong loan, pagbabayad), at ang template ng kontrata.\n2. Empleyado (Loan Ko): mag-apply at maghintay ng aprubal. Puwedeng kanselahin habang Pending.\n3. Approver: aprubahan o tanggihan.\n4. HR: i-print ang kontrata, i-upload ang pirmadong kopya (magiging Active), at markahan ang bawat hulog na bayad.\n> NOTE: Hindi awtomatikong kinakaltas sa payroll ang loan. Ang HR ang nagtatala ng bayad.\n> TIP: May eligibility check (haba ng serbisyo, bilang ng aktibong loan). Puwedeng i-override ng HR sa employee record, na may audit.", "Loan Management Bahagi 8 — HR at Payroll"], ["ERP", "HR Documents", "META: Sino: HR, Lahat | Menu: 📚 HR Documents\nMga form at dokumento (OB form, OT form, atbp.). Bawat file ay may Shared (makikita ng lahat) o Private (HR/Admin lang).", "HR Documents Bahagi 8 — HR at Payroll"], ["ERP", "Memo / Announcement", "META: Sino: HR, Admin | Menu: 📢 Memo\n1. Gumawa ng memo at piliin kung sino ang makakatanggap.\n2. Makikita sa memo kung sino ang nakabasa, nag-acknowledge, at hindi pa.\n3. Pindutin ang Remind para abisuhan ang mga hindi pa nagbubukas.", "Memo / Announcement Bahagi 8 — HR at Payroll"], ["ERP", "Mga Request (Repair / Bilhin / Procurement)", "META: Sino: Lahat | Menu: 🛠️ Mga Request\nPara humiling ng pagpapaayos o pagbili. May kalakip na litrato at routing sa approver na nakatakda sa Position Management.", "Mga Request (Repair / Bilhin / Procurement) Bahagi 8 — HR at Payroll"], ["ERP", "Online / Logout Users", "META: Sino: Admin | Menu: 👥 Online / Logout Users\n- Makikita kung sino ang online at ang huling aktibidad.\n- Logout ay pinapaalis ang user sa lahat ng device.\n- Kung offline na ang user, walang ipapadala at hindi siya mako-kick pagbalik niya.\n- I-logout lahat ay online na non-admin lang ang tinatamaan.", "Online / Logout Users Bahagi 9 — Sistema at Seguridad"], ["Admin", "Audit Logs", "META: Sino: Admin | Menu: 🕵️ Audit Logs\nTalaan ng mahahalagang aksyon (sino, ano, kailan). Gamitin ito kapag may tanong sa pagbabago ng data.", "Audit Logs Bahagi 9 — Sistema at Seguridad"], ["Admin", "Backups", "META: Sino: Admin | Menu: 🛡️ Product Master Auto-Backup\nAwtomatikong kopya ng Product Master at kasaysayan ng bersyon. 🔄 Refresh Backup Logs para makita.", "Backups Bahagi 9 — Sistema at Seguridad"], ["Admin", "System Health", "META: Sino: Admin | Menu: 🩺 System Health\nPagsusuri ng koneksyon at mga posibleng problema sa data.", "System Health Bahagi 9 — Sistema at Seguridad"], ["ERP", "Variance at Reports", "META: Sino: Admin | Menu: 📑 Variance & 3PL Reports\nIhambing ang inaasahan at aktuwal na stock para makita ang shrinkage; 📋 Copy to Sheets at 🖨️ Print.", "Variance at Reports Bahagi 9 — Sistema at Seguridad"], ["ERP", "Branch staff o manager", "1. Mag-login → Place Order para sa mga kailangan ng branch.\n2. Tanggapin ang delivery sa My Deliveries; mag-dispute kung may mali.\n3. Linggu-linggo: Inventory Count at Prime Cost (manager).\n4. Attendance para sa leave, OB, OT. Loan Ko kung mag-a-apply ng loan.", "Branch staff o manager Bahagi 10 — Mabilis na Gabay Ayon sa Tao"], ["ERP", "Commissary", "1. Order Fulfillment Queue → ihanda at ipadala.\n2. Plant Inventory at Direct Receiving para sa stock.\n3. Report Spoilage kapag may nasira.\n4. Daily Price Sheet at AR Ledger para sa singilan.", "Commissary Bahagi 10 — Mabilis na Gabay Ayon sa Tao"], ["ERP", "HR", "1. Employee DB (filter, Import/Export), Position Management.\n2. Attendance at Leave; Payroll; Loan Management.\n3. Memo at HR Documents.", "HR Bahagi 10 — Mabilis na Gabay Ayon sa Tao"], ["ERP", "Accounting", "1. AR Ledger: itala ang bayad. A/P Invoices: bayaran ang supplier.\n2. Accounting (Books): Gastos/Bill, Bank Rec, ulat, VAT/EWT.\n3. Katapusan ng buwan: tapusin ang Bank Rec, suriin ang Trial Balance, i-lock ang buwan.", "Accounting Bahagi 10 — Mabilis na Gabay Ayon sa Tao"], ["Admin", "Admin / Super Admin", "1. Users at Menu Visibility, Company at Branding.\n2. Products, Vendors, Customers.\n3. Regular na tingin sa Audit Logs, Backups at System Health.", "Admin / Super Admin Bahagi 10 — Mabilis na Gabay Ayon sa Tao"], ["ERP", "Karaniwang problema", "| Problema | Dahilan | Solusyon |\n| \"No access\" o \"Missing or insufficient permissions\" | Hindi pa na-publish ang bagong rules, o walang access ang user | I-publish ang firestore.rules; tingnan ang User Access; mag-logout at login |\n| Hindi lumalabas ang bagong menu | Naka-hide sa Menu Visibility, o cache | I-check sa Menu Visibility; Ctrl+F5 |\n| Walang laman ang listahan ng sangkap sa BOM | Walang company ang produkto | Piliin ang tamang company; kasama na rin ang SAP items |\n| Hindi balanse ang Journal | Hindi tugma ang debit at credit | Ayusin hanggang berde ang \"✔ Balanse\" |\n| \"Naka-lock ang buwan\" | May month-end lock | Palitan ang petsa o i-unlock ng Admin |\n| Na-logout agad ang user pagkabukas | Napadalhan ng logout habang naka-sign in | Gamitin ang Logout na may online na user lang |\n| Mali ang presyo sa branch | SRP ang ipinapakita sa branch | Itama ang SRP Whole/Loose sa Products Master |\n| Hindi gumagana ang Import CSV | Mali ang header o format ng petsa | I-download ang Template; YYYY-MM-DD ang petsa |\n| Walang nakikitang data pagkatapos ng update | Cache | Ctrl+F5 |", "Karaniwang problema Bahagi 11 — Troubleshooting at Reference"], ["ERP", "Mga CSV template (columns)", "| Module | Mga column |\n| Employee | Employee_ID, First_Name, Last_Name, Position, Department, Base_Salary, Status, Hire_Date, Companies, at iba pa (gamitin ang 📄 Template) |\n| Product | itemName, code, wholePrice, loosePrice, cost_whole, cost_loose, supplier_price, content_whole, content_loose, content_unit |\n| COA | Code, Name, Type (Asset/Liability/Equity/Revenue/Expense), Bank |\n| Journal | Date, Ref, Memo, Account, Debit, Credit, Description |\n| Bank statement | Date, Amount (o Deposit at Withdrawal) |", "Mga CSV template (columns) Bahagi 11 — Troubleshooting at Reference"], ["ERP", "Talasalitaan", "| Salita | Kahulugan |\n| SRP | Suggested Retail Price; presyong binabayaran ng branch |\n| Whole / Loose | Buong yunit / hiwalay na yunit (hal. kahon / piraso) |\n| BOM | Bill of Materials; recipe |\n| AR / AP | Accounts Receivable (dapat singilin) / Accounts Payable (dapat bayaran) |\n| COA | Chart of Accounts; listahan ng accounts |\n| Debit / Credit | Dalawang panig ng bawat entry; dapat magbalanse |\n| VAT / EWT | Value-added tax / Expanded withholding tax |\n| 2307 | Certificate ng buwis na na-withhold |\n| SIL | Service Incentive Leave |\n| Prime Cost | Food cost + labor cost |\n\n| LST | Schedule at manning ng mga tauhan |", "Talasalitaan Bahagi 11 — Troubleshooting at Reference"], ["ERP", "Mga paalala sa seguridad", "- Ang bawat tao ay may sariling account; huwag magbahagi ng password.\n- Ang cost, sahod at loan ay nakatago sa mga walang karapatan, at ipinapatupad ito ng database rules.\n- Regular na i-export at itabi ang mahahalagang data (Employee, Journal, Product).\n- Para sa BIR, ipa-review sa accountant ang mga ulat at ang paggamit ng ERP bilang opisyal na books.", "Mga paalala sa seguridad Bahagi 11 — Troubleshooting at Reference"], ["POS", "Magbukas ng araw (Opening) at Shift", "1. Buksan ang POS → Shift.\n2. Ilagay ang opening cash (kailangan ito).\n3. Pindutin ang Magbukas at i-confirm.\nTandaan: kung may hindi pa na-Z-read na nakaraang araw, kailangan munang isara iyon. Ang business day ay pinuputol ng 5 AM.", "Magbukas ng araw (Opening) at Shift opening shift cash araw"], ["POS", "Z-read / Pagsasara ng araw", "1. Siguraduhing walang bukas na table (i-settle o i-cancel muna).\n2. Shift → Z-read.\n3. Bilangin ang cash at ilagay; ihahambing ito sa inaasahan.\n4. I-confirm. May bilang na lalabas sa button kung may bukas pang table na humaharang.", "Z-read / Pagsasara ng araw zread z-read isara eod"], ["POS", "Counter sale (walang table)", "1. POS (Counter) tab → pindutin ang mga item para ilagay sa cart.\n2. Piliin ang channel (Dine-in, Take-out, Foodpanda, Grab) sa itaas.\n3. Pindutin ang Bayad, piliin ang paraan, at i-confirm.\nAng Foodpanda/Grab ay item lang na may presyo ng channel ang lalabas; ilagay ang Order No. ng app.", "Counter sale (walang table) counter cart channel grab foodpanda"], ["POS", "Table: magbukas at kumuha ng order", "1. Tables tab → pindutin ang table → ilagay ang pax.\n2. Order → piliin ang Dine-in o Take-out → pumili ng item → Send.\n3. Awtomatikong napi-print ang ticket sa kusina sa background.\nIsang user lang ang puwedeng gumamit ng table; kung iba ang may hawak, kailangan ng manager PIN para sa takeover.", "Table: magbukas at kumuha ng order table order pax"], ["POS", "Magdagdag ng order sa table (Order 2, 3…)", "1. Pindutin ang table na may order.\n2. Bagong order → piliin Dine-in o Take-out at kung para kanino (customer/member).\n3. Send. Nananatiling nakikita ang naunang order; iisang resibo pa rin sa dulo.", "Magdagdag ng order sa table (Order 2, 3…) add order bagong order"], ["POS", "Split bill ayon sa customer", "1. Habang kumukuha ng order, piliin ang may-ari (customer/member) ng bawat order.\n2. Sa bill/pagbabayad, hahatiin ito ayon sa may-ari.\n3. Bayaran ang bawat bill nang hiwalay.", "Split bill ayon sa customer split hati bill owner"], ["POS", "Ilipat ang table / ilipat ng layout", "1. Buksan ang table → Ilipat.\n2. Piliin ang bagong table (puwede sa ibang layout).\nNaitatala ito sa Table History.", "Ilipat ang table / ilipat ng layout move ilipat table layout"], ["POS", "Table Layouts (Main, Extension, Yakitori, Event)", "1. Tables tab → Edit layout (manager/admin).\n2. Magdagdag ng layout gamit ang + at ilagay ang pangalan.\n3. Ilagay at ayusin ang mga table; i-save.\nReal-time ang status ng table sa lahat ng device.", "Table Layouts (Main, Extension, Yakitori, Event) layout floor plan table setup"], ["POS", "Kitchen ticket: reprint at 🔥 Fire", "1. Sa order row, pindutin ang 🔁 Kusina para mag-reprint (para sa hindi pa lumalabas).\n2. Para sa Course 2/3, naka-hold ang item; pindutin ang 🔥 Fire kapag handa na.\n3. Ang Course ng item ay itinatakda sa Menu (Course 1/2/3) o sa cart gamit ang C1/C2/C3.", "Kitchen ticket: reprint at 🔥 Fire kitchen reprint fire course ticket"], ["POS", "Bayad: cash, e-wallet, card, split payment", "1. Bayad → piliin ang paraan (Cash, GCash/Maya/QR Ph, Card, atbp.).\n2. Para sa cash, gamitin ang tap-pad ng bills at coins.\n3. Para sa split, magdagdag ng ilang paraan; kinukuwenta ang natitira.\n4. I-confirm; ipi-print ang resibo.", "Bayad: cash, e-wallet, card, split payment bayad payment cash gcash split"], ["POS", "Voucher", "1. Bayad → Voucher.\n2. I-type ang series number (hal. KV-000123 o 123).\n3. Isang beses lang magagamit; walang sukli; bawal sa order na may discount.\n4. Kung kulang, dagdagan ng cash/card.\nKailangang approved at may naka-assign na may-ari ang voucher (ERP → Vouchers).", "Voucher voucher series"], ["POS", "Gift Card at Loyalty Points", "1. Mag-issue/load/void ng gift card sa 🎁 Gift Card / Points tab (manager).\n2. Bayad → Gift Card: i-type ang series at halaga; nababawasan ang balanse (walang sukli).\n3. Points: piliin muna ang member; Bayad → Points.\n4. Ang points ay kinikita ng member sa bawat bayad kapag naka-on ang Loyalty settings.", "Gift Card at Loyalty Points gift card points loyalty"], ["POS", "Discount (Senior, PWD, Comp, manual)", "1. Bayad → Discount.\n2. Piliin ang uri; kailangan ng manager code (exempt ang admin).\n3. Para sa isang item lang, gamitin ang 🏷️ sa line.\n4. Puwedeng ₱ o %.\nNaka-log sa Table History kung sino ang nag-apply.", "Discount (Senior, PWD, Comp, manual) discount senior pwd comp"], ["POS", "Void at Reprint", "1. Sales/History → piliin ang sale.\n2. Void (manager code, ilagay ang dahilan) o Print para sa kopya.\nNaibabalik ang voucher, gift card at points kapag na-void.", "Void at Reprint void reprint resibo"], ["POS", "Table History", "1. Table History tab (manager/admin).\n2. Piliin ang petsa.\nMakikita kung sino ang nag-punch, kailan, at ang void/discount/takeover.", "Table History history audit sino"], ["POS", "Reservations", "1. Reservations → Bago.\n2. Piliin ang petsa at oras, table sa layout map (o Buong layout / meeting room), at guest.\n3. Advance order: hanapin ang menu (searchable); kung required ang membership, pumili ng member muna.\n4. Save. 30 minuto bago ang oras, may alarm para tawagan at kumpirmahin ang guest.\nKapag uupuan ang table bago ang reservation (hanggang 6 PM), may babala.", "Reservations reservation reserve meeting room"], ["POS", "Meeting room at minimum spend", "Ang meeting room ay may bayad sa renta. Kapag umabot ang order sa minimum spend (hal. ₱16,000), hindi na sisingilin ang renta. Itakda ito sa table editor.", "Meeting room at minimum spend meeting room rent minimum spend"], ["POS", "Kitchen cut-off (9 PM)", "Pagkatapos ng oras na itinakda sa Setup, hindi makakapag-order maliban kung admin o manager code ang gamit.", "Kitchen cut-off (9 PM) cutoff 9pm"], ["POS", "Members at Membership", "1. Members tab → hanapin ang member (ID o pangalan, kahit gitna ng salita) → Hanapin.\n2. Ang principal ang sinisingil; ang dependents (asawa/anak) ay sumusunod sa principal.\n3. Kung inactive ang principal, hindi makakapag-charge ang dependents.\n4. Para sa bulk na club: i-check ang mga resulta → piliin ang club → Assign.", "Members at Membership member membership principal dependent"], ["POS", "Clubs at Statement", "1. Clubs tab → piliin ang club at buwan.\n2. Makikita ang buwanang charge, share ng club (%) at balanse.\n3. 👥 Mga member ng club para magdagdag/mag-alis.\n4. I-mark ang bawat charge: billed, paid, o disputed.", "Clubs at Statement club statement charge member"], ["POS", "Member Charge at Pirma", "Kapag sa member ang bayad, hihingi ng pirma ng customer (kung naka-on). Ang club ang naniningil sa member at babayaran ng accounting.", "Member Charge at Pirma member charge pirma signature"], ["POS", "Menu: magdagdag, i-edit, at Course", "1. Menu tab (admin) → Bagong item.\n2. Ilagay ang pangalan, kategorya, presyo, VAT, at sangkap (gramo).\n3. Piliin ang Kitchen station; puwedeng lagyan ng oras (hal. Main 11:00–16:00, Yakitori 16:01–23:59).\n4. Itakda ang Course (1/2/3).\n5. Presyo ng Grab/Foodpanda: ilagay sa channel price.", "Menu: magdagdag, i-edit, at Course menu item station course"], ["POS", "Menu: bulk upload (CSV)", "1. Menu → ⬆️ Bulk upload.\n2. I-download ang template, punan, at i-upload.\n3. Suriin ang preview (bago, update, may mali).\n4. I-save. Ang kapangalan ay ina-update.", "Menu: bulk upload (CSV) menu csv upload bulk"], ["POS", "Events at Event Menu", "1. Events → Bagong event (pangalan at petsa).\n2. Piliin ang regular na menu na gagamitin.\n3. 📋 Kopyahin mula sa Main Menu para gumawa ng kopya na may sariling presyo at grammage.\n4. ✏️ i-edit ang kopya para sa sukat ng sangkap.", "Events at Event Menu event menu"], ["POS", "Batch Prep", "Gamitin para sa mga paghahanda na sangkap ng ibang item (puwedeng nested). Itakda ang yield at gamitin ito bilang sangkap sa menu.", "Batch Prep batch prep"], ["POS", "Setup: resibo, VAT, service charge", "1. Setup tab.\n2. Ilagay ang legal name, TIN, address, VAT status.\n3. Service charge: on/off at kung ipapakita sa resibo.\n4. Itago ang membership info sa resibo (asterisk).\n5. Opening, cut-off, at reservation alarm settings.", "Setup: resibo, VAT, service charge setup resibo vat service charge"], ["POS", "Printers at Format ng Ticket/Bill", "1. Printers tab: ilagay ang printer ng bawat station.\n2. Format: piliin ang preset (Standard, Tokiya, Tanoshi, Octopos), laki ng font, logo, at privacy ng customer.\n3. Tingnan ang preview bago i-save.", "Printers at Format ng Ticket/Bill printer format ticket bill logo"], ["POS", "Waiter mode (📱)", "Malalaking button para sa phone/tablet: ➕ Order, 🔔 Bill (ipinaaalam sa cashier), 👁 Tingnan, 🔥 Fire.", "Waiter mode (📱) waiter handheld"], ["POS", "QR Self-ordering", "1. 📱 Waiter → 📲 QR (manager): i-sync ang menu, i-on, at i-print ang QR ng bawat table.\n2. Ang customer ay nag-scan, pumipili, at nagpapadala.\n3. 📥 QR inbox: tanggapin para mapunta sa kusina, o tanggihan.\nKailangan na may bukas na table.", "QR Self-ordering qr order self order"], ["POS", "Daily at Mall Sales Report", "Sa Reports, piliin ang Daily/Mall: benta kada araw, rent %, at CSV export.", "Daily at Mall Sales Report report daily mall sales"], ["POS", "Task tray at pag-reload", "Ang mahahabang gawain (backup, import, upload) ay may status label sa gilid na tuloy kahit isara ang modal. May babala kung magre-reload habang may tumatakbo.", "Task tray at pag-reload status label loading backup"]];
  let FAQ = [], TK = [], ST = { q: '', ctx: 'erp', user: {}, admin: false, root: null, tab: 'ask', cat: '' };
  const slug = s => N(s).replace(/[^a-z0-9]+/g, '-').slice(0, 60);
  async function load() {
    FAQ = SEED.map((x, i) => ({ id: 'seed' + i, cat: x[0], q: x[1], a: x[2], kw: x[3], seed: true, art: false })).concat(BOOK.map((x, i) => ({ id: 'art' + i, cat: x[0], q: x[1], a: x[2], kw: x[3], seed: true, art: true }))).filter(f => f.cat !== 'Admin' || ST.admin);
    try { const s = await db.collection('help_faq').get(); s.forEach(d => { const x = d.data(); FAQ.push(Object.assign({ id: d.id, seed: false }, x)); }); } catch (e) {}
    try { const em = String(ST.user.email || '').toLowerCase(); const s = await db.collection('help_tickets').get(); TK = []; s.forEach(d => { const x = Object.assign({ id: d.id }, d.data()); if (ST.admin || String(x.email || '').toLowerCase() === em) TK.push(x); }); TK.sort((a, b) => String(b.at).localeCompare(String(a.at))); } catch (e) { TK = []; }
  }
  function rank(q) {
    const w = N(q).split(/[^a-z0-9ñ]+/).filter(x => x.length > 1); if (!w.length) return [];
    return FAQ.filter(f => ST.cat ? f.cat === ST.cat : true).map(f => { const h = N(f.q + ' ' + (f.kw || '')), b = N(f.a); let s = 0; w.forEach(x => { if (h.split(/[^a-z0-9ñ]+/).some(t => t === x)) s += 4; else if (h.includes(x)) s += 2.5; if (b.includes(x)) s += 1; }); return [f, s]; }).filter(x => x[1] > 0).sort((a, b) => b[1] - a[1]).map(x => x[0]);
  }
  /* Seguridad: hindi nagbibigay ng credentials/laman ng database ang bot; panggabay lang sa paggamit. */
  const SENS = /(password|pasword|pass\s*word|\bpin\b|passcode|credential|\botp\b|secret|api\s*key|token|manager\s*code|code\s*ng|pin\s*ng|password\s*ni|password\s*ng|login\s*ni|account\s*ni|sino\s*ang\s*(may|nag)|balanse\s*ni|sweldo|salary|sahod|sales\s*ni|ilan\s*ang\s*benta|database|firestore|admin\s*access|(ibigay|bigyan|grant|payagan)[^.?!]{0,30}access|i-?grant|gawin\s*akong\s*admin|burahin\s*ang\s*log|i-?bypass|hack)/i;
  const isSens = q => SENS.test(String(q || ''));
  function draw() {
    const r = ST.root; if (!r) return; const sens = ST.q.trim() && isSens(ST.q); const cats = [...new Set(FAQ.map(f => f.cat))].sort(), L = ST.q.trim() ? rank(ST.q) : FAQ.filter(f => !ST.cat || f.cat === ST.cat).slice().sort((a, b) => String(a.cat).localeCompare(String(b.cat))), open = TK.filter(t => t.status !== 'answered').length;
    r.innerHTML = `<div style="max-width:820px;margin:0 auto;"><h3 style="margin:.2rem 0;">❓ Tulong — mga Article at FAQ</h3><div style="font-size:.85rem;color:#64748b;margin-bottom:.5rem;">I-type ang tanong mo (hal. "paano mag-void", "saan ang backup"). Hahanapin ko ang pinakamalapit na sagot; kung wala, puwede kang magpadala ng ticket sa admin.</div>
    <div style="display:flex;gap:.3rem;margin-bottom:.4rem;"><input id="kh-q" type="search" placeholder="🔎 Magtanong…" value="${E(ST.q)}" style="flex:1;font-size:16px;" onkeydown="if(event.key==='Enter')kHelp.ask()"><button class="btn btn-primary" onclick="kHelp.ask()">Hanapin</button></div>
    <div style="display:flex;gap:.3rem;flex-wrap:wrap;margin-bottom:.5rem;">${['', ...cats].map(c => `<button class="btn ${ST.cat === c ? 'btn-primary' : 'btn-secondary'} btn-sm" onclick="kHelp.cat('${E(c)}')">${c || 'Lahat'}</button>`).join('')}<button class="btn ${ST.tab === 'tix' ? 'btn-primary' : 'btn-secondary'} btn-sm" onclick="kHelp.tab('tix')">🎫 Mga ticket ${open ? '(' + open + ')' : ''}</button>${ST.admin ? '<button class="btn btn-secondary btn-sm" onclick="kHelp.edit(\'\')">➕ Magdagdag ng FAQ</button>' : ''}</div>
    ${ST.tab === 'tix' ? tixHtml() : sens ? `<div style="border:1px solid #fca5a5;background:#fef2f2;border-radius:.6rem;padding:.7rem;color:#7f1d1d;">🔒 Hindi ako makapagbibigay ng password, PIN, code, o impormasyon/laman ng sistema ng ibang tao, at hindi ako makapagbibigay ng access. Gabay lang ako sa paggamit ng ERP at POS. Kung kailangan mo ng reset o access, <button class="btn btn-primary btn-sm" onclick="kHelp.ticket()">🎫 magpadala ng ticket sa admin</button> at sila ang magpapasya.</div>` : `${ST.q.trim() && !L.length ? `<div style="border:1px solid #fcd34d;background:#fffbeb;border-radius:.6rem;padding:.7rem;">Walang nahanap na sagot para sa "<b>${E(ST.q)}</b>". <button class="btn btn-primary btn-sm" onclick="kHelp.ticket()">🎫 Magpadala ng tanong sa admin</button></div>` : ''}
    ${L.slice(0, ST.q.trim() ? 6 : 400).map((f, i, arr) => `${!ST.q.trim() && (i === 0 || arr[i - 1].cat !== f.cat) ? `<h4 style="margin:.8rem 0 .2rem;">${E(f.cat === 'POS' ? '🛒 POS' : f.cat === 'Admin' ? '🛠️ Admin' : f.cat === 'ERP' ? '🏢 ERP' : f.cat)}</h4>` : ''}<details ${ST.q.trim() && i === 0 ? 'open' : ''} style="border:1px solid #e2e8f0;border-radius:.6rem;padding:.5rem .7rem;margin:.3rem 0;background:#fff;color:#0f172a;"><summary style="cursor:pointer;font-weight:700;">${E(f.q)} <small style="color:#64748b;font-weight:400;">${E(f.cat)}</small></summary><div style="margin-top:.4rem;white-space:pre-wrap;font-size:.92rem;">${E(f.a)}</div>${ST.admin && !f.seed ? `<div style="margin-top:.4rem;"><button class="btn btn-secondary btn-sm" onclick="kHelp.edit('${f.id}')">✏️</button> <button class="btn btn-danger btn-sm" onclick="kHelp.del('${f.id}')">🗑️</button></div>` : ''}</details>`).join('')}
    ${ST.q.trim() && L.length ? `<div style="margin-top:.5rem;font-size:.85rem;color:#64748b;">Hindi ito ang hinahanap mo? <a href="javascript:void(0)" onclick="kHelp.ticket()">Magpadala ng ticket sa admin</a></div>` : ''}`}</div>`;
  }
  function tixHtml() {
    if (!TK.length) return '<div style="padding:.8rem;color:#64748b;">Wala pang ticket.</div>';
    return TK.map(t => `<div style="border:1px solid ${t.status === 'answered' ? '#86efac' : '#fcd34d'};border-radius:.6rem;padding:.6rem;margin:.3rem 0;background:#fff;color:#0f172a;"><div style="font-size:.78rem;color:#64748b;">${E(String(t.at).slice(0, 16).replace('T', ' '))}${ST.admin ? ' · ' + E(t.name || t.email) + ' (' + E(t.ctx || '') + ')' : ''} · ${t.status === 'answered' ? '✅ Nasagot' : '⏳ Hinihintay'}</div><div style="font-weight:700;">${E(t.q)}</div>${t.a ? `<div style="margin-top:.3rem;background:#f0fdf4;border-radius:.4rem;padding:.4rem;white-space:pre-wrap;">💬 ${E(t.a)}<div style="font-size:.75rem;color:#64748b;">— ${E(t.answeredByName || '')}</div></div>` : ''}${ST.admin ? `<div style="margin-top:.4rem;"><button class="btn btn-primary btn-sm" onclick="kHelp.reply('${t.id}')">${t.a ? '✏️ Palitan ang sagot' : '💬 Sagutin'}</button>${t.a ? ` <button class="btn btn-secondary btn-sm" onclick="kHelp.toFaq('${t.id}')">➕ Gawing FAQ</button>` : ''} <button class="btn btn-danger btn-sm" onclick="kHelp.delT('${t.id}')">🗑️</button></div>` : ''}</div>`).join('');
  }
  const ask = (m, d) => (window.uiPrompt ? window.uiPrompt(m, d || '') : Promise.resolve(window.prompt(m, d || '')));
  const kHelp = {
    async mount(root, o) { ST = Object.assign({ q: '', cat: '', tab: 'ask' }, o || {}, { root }); root.innerHTML = '<div style="padding:1rem;">Nilo-load…</div>'; await load(); draw(); },
    ask() { ST.q = (document.getElementById('kh-q') || {}).value || ''; ST.tab = 'ask'; draw(); const i = document.getElementById('kh-q'); if (i) { i.focus(); i.setSelectionRange(i.value.length, i.value.length); } },
    cat(c) { ST.cat = c; ST.tab = 'ask'; draw(); }, tab(t) { ST.tab = t; draw(); },
    async ticket() {
      const q = (ST.q || '').trim() || String(await ask('Ano ang tanong o problema mo?', '') || '').trim(); if (!q) return; const more = String((await ask('Dagdag na detalye (opsyonal) — saan screen, anong nangyari:', '')) || '').trim();
      try { await db.collection('help_tickets').add({ q: more ? q + '\n' + more : q, ctx: ST.ctx, email: String(ST.user.email || ''), name: String(ST.user.name || ''), at: new Date().toISOString(), status: 'open', page: String(location.pathname || '').split('/').pop() }); await load(); ST.tab = 'tix'; ST.q = ''; draw(); alert('✅ Naipadala ang ticket sa admin. Makikita mo ang sagot dito sa 🎫 Mga ticket.'); } catch (e) { alert('Hindi naipadala: ' + e.message); }
    },
    async reply(id) { const t = TK.find(x => x.id === id); if (!t) return; const a = await ask('Sagot para kay ' + (t.name || t.email) + ':\n' + t.q, t.a || ''); if (a === null || !String(a).trim()) return; try { await db.collection('help_tickets').doc(id).update({ a: String(a).trim(), status: 'answered', answeredAt: new Date().toISOString(), answeredBy: String(ST.user.email || ''), answeredByName: String(ST.user.name || '') }); await load(); draw(); } catch (e) { alert('Error: ' + e.message); } },
    async toFaq(id) { const t = TK.find(x => x.id === id); if (!t || !t.a) return; const cat = ST.ctx === 'pos' ? 'POS' : 'ERP', q = String(await ask('Tanong para sa FAQ:', t.q.split('\n')[0]) || '').trim(); if (!q) return; try { await db.collection('help_faq').add({ cat, q, a: t.a, kw: '', at: new Date().toISOString(), by: String(ST.user.email || '') }); await load(); draw(); alert('✅ Naidagdag sa FAQ.'); } catch (e) { alert('Error: ' + e.message); } },
    async delT(id) { if (!confirm('Burahin ang ticket?')) return; try { await db.collection('help_tickets').doc(id).delete(); await load(); draw(); } catch (e) { alert('Error: ' + e.message); } },
    async edit(id) {
      const f = FAQ.find(x => x.id === id) || { cat: ST.ctx === 'pos' ? 'POS' : 'ERP', q: '', a: '', kw: '' }, cat = await ask('Kategorya (POS, ERP, o iba):', f.cat); if (cat === null) return; const q = await ask('Tanong:', f.q); if (!q) return; const a = await ask('Sagot:', f.a); if (!a) return; const kw = await ask('Keywords (opsyonal, pang-hanap):', f.kw || '');
      try { const d = { cat: String(cat).trim() || 'ERP', q: String(q).trim(), a: String(a).trim(), kw: String(kw || '').trim(), at: new Date().toISOString(), by: String(ST.user.email || '') }; if (id && !f.seed) await db.collection('help_faq').doc(id).set(d, { merge: true }); else await db.collection('help_faq').add(d); await load(); draw(); } catch (e) { alert('Error: ' + e.message); }
    },
    async del(id) { if (!confirm('Burahin ang FAQ na ito?')) return; try { await db.collection('help_faq').doc(id).delete(); await load(); draw(); } catch (e) { alert('Error: ' + e.message); } },
    _sens: isSens, _rank: q => { ST.cat = ''; return rank(q); }, _seed: () => SEED.slice(), _load: load, _st: () => ST
  };
  window.kHelp = kHelp;
})();
